insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'ms_theatre2_v1'
from (values
('117.212.b.1.A',3,'A seventh grader recalls the exact texture of her grandmother''s quilt to make a scene feel more real. She is using:','["sensory recall", "a curtain call", "a prop list", "blocking notes"]'::jsonb,0,'Sensory memories add realistic detail to characterization.','original'),
('117.212.b.1.A',3,'Recalling how she felt when she lost a favorite toy helps an actor play a scene about loss. This is:','["costume planning", "emotional recall", "set painting", "cue calling"]'::jsonb,1,'Emotional recall uses personal feelings to build a role.','original'),
('117.212.b.1.B',2,'Before a rehearsal, the cast does stretches, tongue twisters and breathing exercises. These are:','["stage cues", "scripts", "warm-up techniques", "reviews"]'::jsonb,2,'Warm-ups prepare voice and body.','original'),
('117.212.b.1.B',3,'Preparing for a role by reading the script, marking lines and thinking about the character is a form of:','["ticket sales", "set striking", "costume repair", "theatre preparation"]'::jsonb,3,'Preparation includes script study.','original'),
('117.212.b.1.C',2,'An actor uses a steady stepping pattern and swinging arms to show a marching soldier. This is a:','["rhythmic movement", "curtain cue", "scene change", "costume change"]'::jsonb,0,'Rhythmic movement has a regular beat.','original'),
('117.212.b.1.C',2,'Reaching wide and opening the chest to show joy is a(n):','["cue", "expressive movement", "prompt", "blackout"]'::jsonb,1,'Expressive movement conveys feeling.','original'),
('117.212.b.1.D',3,'The part of the body that shapes sound into vowels and consonants includes the lips, tongue and:','["shoulders", "knees", "teeth and jaw", "elbows"]'::jsonb,2,'Articulators shape speech sounds.','original'),
('117.212.b.1.D',3,'A resonator in vocal production helps:','["stop the breath", "silence the voice", "lower the volume only", "make the voice richer and louder"]'::jsonb,3,'Resonators amplify and color sound.','original'),
('117.212.b.1.E',2,'The term for the actors'' movement and position on stage planned by the director is:','["blocking", "tagging", "striking", "cueing"]'::jsonb,0,'Blocking is planned movement on stage.','original'),
('117.212.b.1.E',2,'A prop is an object that:','["is a stage area", "an actor handles during a scene", "is a seat", "is part of the building"]'::jsonb,1,'Props are handheld objects used in a show.','original'),
('117.212.b.1.F',3,'Evaluating the structure of a play, a student notes that the exposition:','["lists the cast only", "closes the show", "introduces the characters and setting", "ends the conflict"]'::jsonb,2,'Exposition provides background and context.','original'),
('117.212.b.1.F',4,'A dramatic work in which events lead to a sad ending for the main character is called a:','["parade", "comedy", "farce", "tragedy"]'::jsonb,3,'Tragedies end sadly.','original'),
('117.212.b.2.A',2,'To protect the voice during a long rehearsal, an actor should:','["sip water and avoid yelling", "whisper only", "talk nonstop", "scream the whole time"]'::jsonb,0,'Healthy vocal habits protect the voice.','original'),
('117.212.b.2.A',2,'For safe movement on stage, actors should know the:','["ticket price", "blocking and clear exits", "program cost", "parking spaces"]'::jsonb,1,'Safety includes knowing paths and exits.','original'),
('117.212.b.2.B',3,'In a script, we learn about a character through what he does, what he says and:','["the font used", "the length of the show", "what others say about him", "the ticket cost"]'::jsonb,2,'Characterization is revealed in action, speech and others'' comments.','original'),
('117.212.b.2.B',3,'If other characters call a man a bully, the audience learns about him from:','["costume tags", "his own lines only", "stage lights", "what others say about him"]'::jsonb,3,'Other characters'' comments reveal traits.','original'),
('117.212.b.2.C',3,'An actor playing a proud queen might choose:','["an upright posture and slow, steady movement", "random hopping", "slumped shoulders", "quick giggles"]'::jsonb,0,'Choices must fit the character.','original'),
('117.212.b.2.C',3,'To portray a nervous character, the dialogue might be delivered:','["slowly and calmly", "quickly with small pauses", "in a booming voice", "in a bored monotone"]'::jsonb,1,'Speech patterns reflect emotion.','original'),
('117.212.b.2.D',3,'A dramatic structure includes a beginning, a middle and an end, along with:','["a ticket scan", "no plot", "a conflict that builds and resolves", "random scenes"]'::jsonb,2,'Structure organizes the story.','original'),
('117.212.b.2.D',3,'A group creates a story together where a character wants something and faces an obstacle. They are building:','["a map", "a budget", "a schedule", "dramatic structure"]'::jsonb,3,'Want plus obstacle forms drama.','original'),
('117.212.b.2.E',3,'Speaking clearly so each word is understood is called:','["diction", "striking", "blocking", "cueing"]'::jsonb,0,'Diction is clear pronunciation.','original'),
('117.212.b.2.E',3,'An actor changes her volume and pitch to show anger and then sadness. She is applying:','["set design", "voice techniques to express feelings", "costume repair", "lighting cues"]'::jsonb,1,'Vocal variety expresses emotion.','original'),
('117.212.b.2.F',3,'In life, people often pause before telling bad news. When an actor does this on stage she is:','["skipping lines", "ignoring the script", "imitating real behavior", "ending the scene"]'::jsonb,2,'Drama compares to real life.','original'),
('117.212.b.2.F',4,'Drama heightens real life by:','["hiding characters", "removing all feeling", "avoiding stories", "compressing time and sharpening conflict"]'::jsonb,3,'Plays condense and intensify life.','original'),
('117.212.b.2.G',3,'Improvised scenes include a setting, a character and a plot, so before starting, players decide:','["who, where and what is happening", "the lobby decor", "the program font", "the ticket color"]'::jsonb,0,'Improv needs those basic elements.','original'),
('117.212.b.2.G',3,'A rule that helps scenes grow in improv is to:','["block every idea", "accept and build on your partner''s idea", "ignore the scene", "stop talking"]'::jsonb,1,'Accepting offers builds scenes.','original'),
('117.212.b.3.A',3,'A technical element that supports a character is:','["a lobby poster", "a parking sign", "a costume that fits her role", "a ticket booth"]'::jsonb,2,'Costumes support characterization.','original'),
('117.212.b.3.A',3,'To provide a safe setting on stage, crew members make sure:','["props block the aisles", "lights are left unsecured", "trash is left on stage", "cables are taped down and exits are clear"]'::jsonb,3,'Safety is part of technical planning.','original'),
('117.212.b.3.B',3,'Scenery, lighting, sound, costume and makeup are:','["theatrical elements", "audience items", "ticket forms", "intermissions"]'::jsonb,0,'These are elements of production design.','original'),
('117.212.b.3.B',3,'A sound designer creates:','["costumes", "sound effects and music cues", "scenery", "props only"]'::jsonb,1,'Sound design supports the story.','original'),
('117.212.b.3.C',2,'The role of the director is to:','["sew costumes only", "clean the seats", "guide the vision and organize rehearsals", "sell tickets"]'::jsonb,2,'The director leads the production.','original'),
('117.212.b.3.C',3,'During rehearsals, the director gives actors notes about:','["their grades only", "their lunches", "their commutes", "their performances and blocking"]'::jsonb,3,'Directors give feedback and shape staging.','original'),
('117.212.b.3.D',2,'A lighting board and a sound mixer are examples of:','["theatre technology", "kitchen tools", "gym equipment", "school supplies"]'::jsonb,0,'Boards and mixers are theatre tech.','original'),
('117.212.b.3.D',3,'Using a green screen in a film allows a scene to:','["have no actors", "take place in any imagined setting", "have no story", "be silent"]'::jsonb,1,'Green screen allows added backgrounds.','original'),
('117.212.b.4.A',3,'A play set in Ancient Greece shows how theatre reflects:','["a school lunch", "a modern phone plan", "life in a particular time and place", "a bus route"]'::jsonb,2,'Theatre reflects its context.','original'),
('117.212.b.4.A',3,'A play about immigrants moving to a new country reflects:','["a map legend", "a bank form", "a recipe", "a culture''s experiences"]'::jsonb,3,'Theatre reflects cultural experiences.','original'),
('117.212.b.4.B',3,'A student reads a classic play and sees a conflict that still happens in schools today. This shows the:','["relevance of theatre heritage", "end of theatre", "history of paper", "price of plays"]'::jsonb,0,'Classic plays remain relevant.','original'),
('117.212.b.4.B',3,'Studying how Shakespeare''s plays influenced modern stories explores the influence of:','["parking", "dramatic texts", "lunch menus", "seats"]'::jsonb,1,'Classic texts shape modern writing.','original'),
('117.212.b.4.C',3,'The invention of television changed entertainment because it:','["removed actors", "ended all stories", "brought performances into homes", "stopped writing"]'::jsonb,2,'TV widened access to performance.','original'),
('117.212.b.4.C',3,'The role of film differs from live theatre because film can:','["have no audience", "not tell stories", "not use actors", "be edited and shown many times"]'::jsonb,3,'Film is recorded and editable.','original'),
('117.212.b.5.A',2,'Appropriate audience etiquette at a musical includes:','["applauding at the right moments and staying seated", "walking on stage", "calling out lines", "using flash photos"]'::jsonb,0,'Etiquette respects the show.','original'),
('117.212.b.5.A',2,'At a live play, audience members show respect by:','["leaving the door open", "silencing phones and not recording", "taking photos with flash", "talking to actors"]'::jsonb,1,'Silence and no recording protect the show.','original'),
('117.212.b.5.B',4,'When evaluating a film performance, a viewer looks at how well the actor:','["arrived on time", "shopped for costumes", "portrayed the character believably", "wrote the script"]'::jsonb,2,'Believability measures effectiveness.','original'),
('117.212.b.5.B',4,'A student criticizes a television performance because the actor''s emotions did not match the scene. She is evaluating its:','["length", "color", "cost", "effectiveness"]'::jsonb,3,'Matching emotion to scene is effective acting.','original'),
('117.212.b.5.C',3,'Camera angles, editing and sound mixing are production elements of:','["film and television", "only live stage", "only print", "only radio"]'::jsonb,0,'Film and TV rely on these elements.','original'),
('117.212.b.5.C',3,'Lighting, sets and costumes are production elements shared by:','["art class only", "theatre, film and television", "math class", "gym class"]'::jsonb,1,'Many media use these elements.','original'),
('117.212.b.5.D',3,'A person who designs scenery for productions works in a:','["bank job", "farm job", "theatre vocation", "bus job"]'::jsonb,2,'Scenic design is a theatre career.','original'),
('117.212.b.5.D',3,'Career opportunities in theatre include actor, stage manager and:','["dentist", "banker", "pilot", "costume designer"]'::jsonb,3,'Costume designers are theatre professionals.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
